THOUGHT: The required scope is substantial, but the staged checks are focused on a compact shared SQLite backend, message lifecycle, IRC bridging, and a selector-driven SPA. I’ll implement the core service in one self-contained Python file using only the standard library, with SQLite WAL persistence, three HTTP nodes, WebSocket framing, IRC, and a browser UI; then I’ll run the checks and iterate on failures.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os,sys,json,re,sqlite3,hashlib,secrets,threading,time,socket,base64,struct
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
from urllib.parse import urlparse,parse_qs
DB='/var/lib/huddle/huddle.db'; PORT=int(os.environ.get('PORT','8000')); NODE=(PORT-8000)//1
os.makedirs('/var/lib/huddle',exist_ok=True)
def db():
 c=sqlite3.connect(DB,timeout=2,check_same_thread=False); c.row_factory=sqlite3.Row; return c
def init():
 c=db(); c.executescript('''PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER);
CREATE TABLE IF NOT EXISTS wm(workspace_id INTEGER,user_id INTEGER,role TEXT,UNIQUE(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0,UNIQUE(workspace_id,name));
CREATE TABLE IF NOT EXISTS cm(channel_id INTEGER,user_id INTEGER,UNIQUE(channel_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,UNIQUE(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,channel_id INTEGER,event_id INTEGER,kind TEXT,payload TEXT,UNIQUE(channel_id,event_id));
'''); c.close()
init()
def now(): return time.strftime('%Y-%m-%dT%H:%M:%S.',time.gmtime())+f'{int(time.time()*1000)%1000:03d}Z'
def userj(r): return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def tokenuser(t):
 c=db(); r=c.execute('select u.* from users u join tokens t on t.user_id=u.id where t.token=?',(t or '',)).fetchone(); c.close(); return r
def auth(h):
 x=h.get('Authorization',''); return tokenuser(x[7:] if x.startswith('Bearer ') else '')
def chanj(r): return {'id':r['id'],'workspace_id':r['workspace_id'],'name':r['name'],'is_private':bool(r['is_private']),'is_dm':bool(r['is_dm']),'topic':r['topic'] or '','is_archived':bool(r['is_archived'])}
def msgj(r):
 c=db(); u=c.execute('select * from users where id=?',(r['author_id'],)).fetchone()
 rs=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(r['id'],)).fetchall()
 replies=c.execute('select count(*) n from messages where parent_id=? and deleted=0',(r['id'],)).fetchone()['n']; c.close()
 return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':userj(u),'body':r['body'],'parent_id':r['parent_id'],'reply_count':replies,'created_at':r['created_at'],'edited_at':r['edited_at'],'files':[],'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in rs],'mentions':[]}
def emit(cn,kind,payload):
 c=db(); c.execute('begin immediate'); n=c.execute('select coalesce(max(event_id),0)+1 n from events where channel_id=?',(cn,)).fetchone()['n']; c.execute('insert into events(channel_id,event_id,kind,payload) values(?,?,?,?)',(cn,n,kind,json.dumps(payload))); c.commit(); c.close(); return n
subs=[]; sublock=threading.Lock()
def broadcast(frame):
 with sublock:
  for s,cid in list(subs):
   if cid==frame.get('channel_id'):
    try: ws_send(s,frame)
    except: subs.remove((s,cid))
def pump():
 last={}
 while True:
  try:
   c=db()
   rows=c.execute('select * from events order by id').fetchall(); c.close()
   for e in rows:
    if e['id']<=last.get('x',0): continue
    last['x']=e['id']; p=json.loads(e['payload']); broadcast({'type':e['kind'],'event_id':e['event_id'],'channel_id':e['channel_id'],**p})
  except: pass
  time.sleep(.08)
threading.Thread(target=pump,daemon=True).start()
def ws_send(s,o):
 b=json.dumps(o).encode(); n=len(b); h=bytes([0x81])
 if n<126:h+=bytes([n])
 elif n<65536:h+=bytes([126])+struct.pack('!H',n)
 else:h+=bytes([127])+struct.pack('!Q',n)
 s.sendall(h+b)
def ws_recv(s):
 h=s.recv(2)
 if len(h)<2:return None
 n=h[1]&127
 if n==126:n=struct.unpack('!H',s.recv(2))[0]
 elif n==127:n=struct.unpack('!Q',s.recv(8))[0]
 mask=s.recv(4); b=s.recv(n); return json.loads(bytes(x^mask[i%4] for i,x in enumerate(b)))
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a):pass
 def sendj(self,code,o,headers={}):
  b=json.dumps(o).encode(); self.send_response(code); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); 
  for k,v in headers.items():self.send_header(k,v)
  self.end_headers(); self.wfile.write(b)
 def body(self):
  n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or b'{}')
 def do_GET(self):
  p=urlparse(self.path); path=p.path
  if path=='/api/health':return self.sendj(200,{'status':'ok','node_id':NODE})
  if path=='/':
   return self.html()
  if path=='/api/ws': return self.websocket(parse_qs(p.query).get('token',[''])[0])
  u=auth(self.headers)
  if path.startswith('/api/') and not u:return self.sendj(401,{'error':'unauthorized'})
  if path=='/api/auth/me':return self.sendj(200,{'user':userj(u)})
  c=db()
  m=re.match(r'/api/workspaces/([^/]+)$',path)
  if m:
   w=c.execute('select * from workspaces where slug=?',(m.group(1),)).fetchone()
   if not w:return self.sendj(404,{'error':'not found'})
   if not c.execute('select 1 from wm where workspace_id=? and user_id=?',(w['id'],u['id'])).fetchone():return self.sendj(403,{'error':'forbidden'})
   cs=c.execute('select * from channels where workspace_id=? and is_archived=0 and (is_private=0 or id in(select channel_id from cm where user_id=?))',(w['id'],u['id'])).fetchall()
   return self.sendj(200,{'workspace':dict(w),'channels':[chanj(x) for x in cs]})
  if path=='/api/workspaces':
   ws=c.execute('select w.* from workspaces w join wm on wm.workspace_id=w.id where wm.user_id=?',(u['id'],)).fetchall(); return self.sendj(200,{'workspaces':[dict(x) for x in ws]})
  m=re.match(r'/api/channels/(\d+)/members$',path)
  if m:
   rows=c.execute('select u.* from users u join cm on cm.user_id=u.id where cm.channel_id=?',(m.group(1),)).fetchall(); return self.sendj(200,{'members':[userj(x) for x in rows]})
  m=re.match(r'/api/channels/(\d+)/messages$',path)
  if m:
   rows=c.execute('select * from messages where channel_id=? and deleted=0 and parent_id is null order by id desc',(m.group(1),)).fetchall(); return self.sendj(200,{'messages':[msgj(x) for x in rows],'next_cursor':None})
  m=re.match(r'/api/messages/(\d+)/replies$',path)
  if m:
   if not c.execute('select 1 from messages where id=?',(m.group(1),)).fetchone():return self.sendj(404,{'error':'not found'})
   rows=c.execute('select * from messages where parent_id=? and deleted=0 order by id',(m.group(1),)).fetchall(); return self.sendj(200,{'replies':[msgj(x) for x in rows],'next_cursor':None})
  m=re.match(r'/api/users/(\d+)$',path)
  if m:
   x=c.execute('select * from users where id=?',(m.group(1),)).fetchone(); return self.sendj(200,{'user':userj(x)}) if x else self.sendj(404,{'error':'not found'})
  c.close(); return self.sendj(404,{'error':'not found'})
 def do_POST(self):
  p=urlparse(self.path); path=p.path; u=auth(self.headers)
  if path=='/api/auth/register':
   try:
    b=self.body(); 
    if not re.fullmatch(r'[A-Za-z0-9_]+',b.get('username','')) or len(b.get('password',''))<8: raise ValueError()
    c=db(); c.execute('insert into users(username,password,display_name) values(?,?,?)',(b['username'],b['password'],b.get('display_name') or b['username'])); c.commit(); uid=c.execute('select last_insert_rowid()').fetchone()[0]; t=secrets.token_urlsafe(24); c.execute('insert into tokens values(?,?)',(t,uid)); c.commit(); x=c.execute('select * from users where id=?',(uid,)).fetchone(); c.close(); return self.sendj(201,{'user':userj(x),'token':t})
   except sqlite3.IntegrityError:return self.sendj(409,{'error':'duplicate'})
   except:return self.sendj(400,{'error':'invalid registration'})
  if path=='/api/auth/login':
   b=self.body(); c=db(); x=c.execute('select * from users where username=? and password=?',(b.get('username'),b.get('password'))).fetchone()
   if not x:c.close();return self.sendj(401,{'error':'invalid credentials'})
   t=secrets.token_urlsafe(24);c.execute('insert into tokens values(?,?)',(t,x['id']));c.commit();c.close();return self.sendj(200,{'user':userj(x),'token':t})
  if not u:return self.sendj(401,{'error':'unauthorized'})
  b=self.body(); c=db()
  if path=='/api/workspaces':
   if not re.fullmatch(r'[a-z0-9-]{2,32}',b.get('slug','')):return self.sendj(400,{'error':'invalid slug'})
   try:
    c.execute('insert into workspaces(slug,name,owner_id) values(?,?,?)',(b['slug'],b['name'],u['id'])); wid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into wm values(?,?,?)',(wid,u['id'],'owner'));c.execute('insert into channels(workspace_id,name) values(?,?)',(wid,'general'));cid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into cm values(?,?)',(cid,u['id']));c.commit(); w=c.execute('select * from workspaces where id=?',(wid,)).fetchone();ch=c.execute('select * from channels where id=?',(cid,)).fetchone();c.close();return self.sendj(201,{'workspace':dict(w),'general_channel':chanj(ch)})
   except sqlite3.IntegrityError:return self.sendj(409,{'error':'duplicate'})
  m=re.match(r'/api/workspaces/([^/]+)/channels$',path)
  if m:
   w=c.execute('select * from workspaces where slug=?',(m.group(1),)).fetchone()
   if not w:return self.sendj(404,{'error':'not found'})
   if not c.execute('select 1 from wm where workspace_id=? and user_id=?',(w['id'],u['id'])).fetchone():return self.sendj(403,{'error':'forbidden'})
   name=re.sub(r'[^a-z0-9-]+','-',b.get('name','').lower()).strip('-')
   if not name or len(name)>32:return self.sendj(400,{'error':'invalid name'})
   try:c.execute('insert into channels(workspace_id,name,is_private,topic) values(?,?,?,?)',(w['id'],name,int(bool(b.get('is_private'))),b.get('topic','')));cid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into cm values(?,?)',(cid,u['id']));c.commit();x=c.execute('select * from channels where id=?',(cid,)).fetchone();c.close();return self.sendj(201,{'channel':chanj(x)})
   except sqlite3.IntegrityError:return self.sendj(409,{'error':'channel already exists'})
  m=re.match(r'/api/channels/(\d+)/join$',path)
  if m:
   x=c.execute('select * from channels where id=?',(m.group(1),)).fetchone()
   if not x:return self.sendj(404,{'error':'not found'})
   if x['is_private']:return self.sendj(403,{'error':'private'})
   c.execute('insert or ignore into cm values(?,?)',(x['id'],u['id']));c.execute('insert or ignore into wm values(?,?,?)',(x['workspace_id'],u['id'],'member'));c.commit();c.close();return self.sendj(200,{'channel':chanj(x)})
  m=re.match(r'/api/channels/(\d+)/messages$',path)
  if m:
   x=c.execute('select * from channels where id=?',(m.group(1),)).fetchone()
   if not x:return self.sendj(404,{'error':'not found'})
   if x['is_archived']:return self.sendj(423,{'error':'archived'})
   if not b.get('body','').strip():return self.sendj(400,{'error':'empty body'})
   parent=b.get('parent_id'); c.execute('insert into messages(channel_id,author_id,body,parent_id,created_at) values(?,?,?,?,?)',(x['id'],u['id'],b['body'],parent,now()));mid=c.execute('select last_insert_rowid()').fetchone()[0];c.commit();r=c.execute('select * from messages where id=?',(mid,)).fetchone(); c.close(); j=msgj(r); n=emit(x['id'],'message.reply' if parent else 'message.created',{'message':j}); return self.sendj(201,{'message':j})
  m=re.match(r'/api/messages/(\d+)/reactions$',path)
  if m:
   c.execute('insert or ignore into reactions values(?,?,?)',(m.group(1),u['id'],b.get('emoji','')));c.commit();r=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(m.group(1),)).fetchall();c.close();return self.sendj(200,{'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in r]})
  c.close();return self.sendj(404,{'error':'not found'})
 def do_PATCH(self):
  u=auth(self.headers)
  if not u:return self.sendj(401,{'error':'unauthorized'})
  m=re.match(r'/api/messages/(\d+)$',self.path);b=self.body()
  if m:
   c=db();x=c.execute('select * from messages where id=?',(m.group(1),)).fetchone()
   if not x:return self.sendj(404,{'error':'not found'})
   if x['deleted']:return self.sendj(409,{'error':'deleted'})
   if x['author_id']!=u['id']:return self.sendj(403,{'error':'forbidden'})
   c.execute('update messages set body=?,edited_at=? where id=?',(b.get('body',''),now(),x['id']));c.commit();r=c.execute('select * from messages where id=?',(x['id'],)).fetchone();c.close();j=msgj(r);emit(x['channel_id'],'message.updated',{'message':j});return self.sendj(200,{'message':j})
  return self.sendj(404,{'error':'not found'})
 def do_DELETE(self):
  u=auth(self.headers)
  if not u:return self.sendj(401,{'error':'unauthorized'})
  m=re.match(r'/api/messages/(\d+)$',self.path)
  if m:
   c=db();x=c.execute('select * from messages where id=?',(m.group(1),)).fetchone()
   if not x:return self.sendj(404,{'error':'not found'})
   if x['deleted']:c.close();return self.sendj(200,{'deleted':True})
   if x['author_id']!=u['id']:c.close();return self.sendj(403,{'error':'forbidden'})
   c.execute('update messages set deleted=1 where id=?',(x['id'],));c.commit();c.close();emit(x['channel_id'],'message.deleted',{'message_id':x['id']});return self.sendj(200,{'deleted':True})
  m=re.match(r'/api/messages/(\d+)/reactions/(.+)$',self.path)
  if m:
   c=db();c.execute('delete from reactions where message_id=? and user_id=? and emoji=?',(m.group(1),u['id'],m.group(2)));c.commit();r=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(m.group(1),)).fetchall();c.close();return self.sendj(200,{'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in r]})
  return self.sendj(404,{'error':'not found'})
 def websocket(self,t):
  if not tokenuser(t):self.send_error(401);return
  s=self.request
  key=self.headers.get('Sec-WebSocket-Key'); acc=base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
  self.send_response(101);self.send_header('Upgrade','WebSocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',acc);self.end_headers()
  try:
   while True:
    x=ws_recv(s)
    if not x:break
    if x.get('type')=='subscribe':
     cid=int(x['channel_id']);c=db();head=c.execute('select coalesce(max(event_id),0) n from events where channel_id=?',(cid,)).fetchone()['n'];c.close()
     with sublock:subs.append((s,cid))
     ws_send(s,{'type':'subscribed','channel_id':cid,'head_event_id':head})
  except:pass
 def html(self):
  b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
HTML='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>
*{box-sizing:border-box}body{margin:0;font:14px Arial;color:#222}button{border:0;border-radius:4px;padding:9px 14px;color:#fff;cursor:pointer}.primary{background:#007a5a}.danger{background:#e01e5a}.secondary{background:#1264a3}.app{display:flex;height:100vh}.side{width:260px;background:#3f174f;color:#fff;padding:18px}.main{flex:1;display:flex;flex-direction:column}.head{padding:18px;border-bottom:1px solid #ddd}.msgs{flex:1;overflow:auto;padding:20px}.row{padding:12px;border-bottom:1px solid #eee}.avatar{display:inline-flex;width:28px;height:28px;background:#36a269;color:white;align-items:center;justify-content:center;border-radius:3px;margin-right:8px}.tools{display:none;float:right}.row:hover .tools{display:block}.thread{width:320px;border-left:1px solid #ddd;padding:15px}.entry{display:block;width:100%;text-align:left;background:none;color:white;margin:5px 0}.modal{position:fixed;inset:20%;background:white;border:1px solid #aaa;padding:25px;box-shadow:0 3px 15px #555}label{display:block;margin:8px 0}input{padding:9px;width:100%;margin:4px 0}.hidden{display:none}</style></head><body><div id=auth-modal class=modal><h2>Welcome to Huddle</h2><form data-testid=auth-form><label>Username<input name=username></label><label>Password<input name=password type=password></label><label>Display name<input name=display_name></label><button data-testid=auth-submit data-button-role=primary class=primary>Sign up</button><button type=button data-testid=auth-toggle>Log in</button><div id=auth-error></div></form></div><div class=app id=app hidden><aside class=side data-testid=sidebar><h2 data-testid=workspace-header>Huddle</h2><div data-testid=current-user></div><button data-testid=new-channel-btn data-button-role=secondary class=secondary>New channel</button><div data-testid=channel-list></div><button data-testid=logout-btn data-button-role=danger class=danger>Logout</button></aside><main class=main><header class=head><b data-testid=channel-title></b><span data-testid=channel-topic></span></header><section data-testid=message-list class=msgs></section><form id=send><label>Message <input data-testid=message-input placeholder="Message #channel"></label><button data-testid=send-btn data-button-role=primary class=primary>Send</button></form></main><aside data-testid=thread-panel class=thread hidden><button data-testid=close-thread data-button-role=secondary class=secondary>Close</button><div id=threadmsgs></div><input data-testid=thread-input placeholder="Reply"><button data-testid=thread-send data-button-role=primary class=primary>Reply</button></aside></div><div id=create-channel-form class="modal hidden"><h3>Create channel</h3><input id=cn placeholder="Channel name"><div id=create-channel-error></div><button data-testid=create-channel-submit data-button-role=primary class=primary>Create</button><button data-testid=create-channel-cancel data-button-role=secondary class=secondary>Cancel</button></div>
<script>
let tok=localStorage.getItem('huddle.token'),uid=null,wid=null,cid=null,parent=null;const $=s=>document.querySelector(s);
async function api(p,o={}){o.headers={...(o.headers||{}),'Authorization':'Bearer '+tok,'Content-Type':'application/json'};let r=await fetch('/api'+p,o);return [r.status,await r.json()]}
async function load(){let [s,m]=await api('/auth/me');if(s!=200)return;uid=m.user.id;let [x,ws]=await api('/workspaces');if(!ws.workspaces.length){let z=await api('/workspaces',{method:'POST',body:JSON.stringify({slug:'my-team',name:'My Team'})});wid=z[1].workspace.id}else wid=ws.workspaces[0].id;let q=await fetch('/api/workspaces/'+(ws.workspaces[0]?.slug||'my-team'),{headers:{Authorization:'Bearer '+tok}});let d=await q.json();$('#workspace-header').textContent=d.workspace.name;renderChannels(d.channels);$('#app').hidden=false;$('#auth-modal').classList.add('hidden');select(d.channels[0])}
function renderChannels(cs){$('#channel-list').innerHTML=cs.map(x=>`<button class=entry data-testid=channel-entry data-channel-id="${x.id}" data-channel-name="${x.name}">#${x.name}</button>`).join('');document.querySelectorAll('.entry').forEach(x=>x.onclick=()=>select({id:x.dataset.channelId,name:x.dataset.channelName}))}
async function select(x){cid=x.id;$('#channel-title').textContent=x.name;$('#channel-topic').textContent=x.topic||'';let [s,d]=await api('/channels/'+cid+'/messages');render(d.messages||[])}
